{"code":"def solve(m):
    n=len(m)
    if n==0:
        return 1
    # Bareiss algorithm (fraction-free)
    a=[row[:] for row in m]
    prev=1
    det_sign=1
    for k in range(n-1):
        # pivot if zero
        if a[k][k]==0:
            swap=-1
            for i in range(k+1,n):
                if a[i][k]!=0:
                    swap=i
                    break
            if swap==-1:
                return 0
            a[k],a[swap]=a[swap],a[k]
            det_sign*=-1
        for i in range(k+1,n):
            for j in range(k+1,n):
                a[i][j]=(a[i][j]*a[k][k]-a[i][k]*a[k][j])//prev
            a[i][k]=0
        prev=a[k][k]
        if prev==0:
            return 0
    return det_sign*a[n-1][n-1]","task_id":"T25"}

