def solve(m):
    if m is None or m == []:
        return 1
    n = len(m)
    if n == 0:
        return 1
    # handle [[]] or empty rows
    try:
        if all(len(row) == 0 for row in m):
            return 1
    except Exception:
        return 1
    a = [list(row) for row in m]
    # ensure square
    if any(len(row) != n for row in a):
        # fall back: if 0-size treat as 1
        return 1
    if n == 1:
        return int(a[0][0])
    prev = 1
    swaps = 0
    for k in range(n - 1):
        if a[k][k] == 0:
            swap = -1
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap == -1:
                return 0
            a[k], a[swap] = a[swap], a[k]
            swaps += 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * a[k][k] - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = a[k][k]
        if prev == 0:
            return 0
    det = a[n - 1][n - 1]
    if swaps % 2 == 1:
        det = -det
    return int(det)

