def solve(*args, **kwargs):
    if kwargs:
        y = kwargs.get('year', kwargs.get('y'))
        m = kwargs.get('month', kwargs.get('m'))
        d = kwargs.get('day', kwargs.get('d'))
    elif len(args)==3:
        y,m,d=args
    elif len(args)==1:
        a=args[0]
        if isinstance(a,(list,tuple)):
            y,m,d=a[0],a[1],a[2]
        else:
            y,m,d=a,'',''
    else:
        y,m,d=args
    y=int(y); m=int(m); d=int(d)
    try:
        import datetime
        if 1<=y<=9999:
            return datetime.date(y,m,d).strftime('%A')
    except Exception:
        pass
    yy=y
    mm=m
    dd=d
    yy -= (mm<=2)
    era = (yy//400 if yy>=0 else (yy-399)//400)
    yoe = yy - era*400
    mp = (mm-3)%12
    doy = (153*mp+2)//5 + dd-1
    doe = yoe*365 + yoe//4 - yoe//100 + doy
    days = era*146097 + doe - 719468
    idx = (days+3)%7
    names=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
    return names[idx]
